fn main() {
    let s = "ab"
    print(str_len(s))
    let mut_total = 0
    for i in range(0, 3) {
        let t = s
        mut_total = mut_total + str_len(t)
    }
    print(mut_total)
}

fn str_len(s: Str) -> Int {
    let mut_chars = 0
    for c in chars(s) {
        mut_chars = mut_chars + 1
    }
    mut_chars
}

fn chars(s: Str) -> Vec<Str> {
    let mut_chars = vec()
    for i in range(0, str_len(s)) {
        mut_chars.push(get(s, i)?)
    }
    mut_chars
}

fn get(s: Str, i: Int) -> Option<Str> {
    if i >= str_len(s) {
        None
    } else {
        Some(Str(s.chars().nth(i).unwrap()))
    }
}

